package jp.tapmarker;
import java.util.*;
public final class ObservationLearnerTest {
 static int checks;static void check(boolean v,String label){if(!v)throw new AssertionError(label);checks++;}
 static int pixel(int x,int y,int kind,int w,int h){float u=x/(float)w,v=y/(float)h;int r=(int)(40+u*90),g=(int)(70+v*80),b=65;if((u>.2&&u<.8&&v>.18&&v<.31)||(u>.15&&u<.85&&v>.67&&v<.83)){r=kind==0?220:kind==1?35:120;g=kind==0?90:kind==1?180:40;b=kind==0?35:kind==1?110:220;if(((int)(u*80)+(int)(v*180))%5<2){r/=2;g/=2;b/=2;}}return 0xff000000|r<<16|g<<8|b;}
 static ObservationLearner.Frame frame(int kind){return ObservationLearner.Frame.capture(320,720,(x,y)->pixel(x,y,kind,320,720));}
 static ObservationLearner.Step step(ObservationLearner.Frame a,ObservationLearner.Frame b,float x,float y){ObservationLearner.Step s=new ObservationLearner.Step();s.before=a;s.peer=a;s.after=b;s.path=new float[]{x,y,x,y};return s;}
 static Map<String,float[]> samples(PhaseEngine e,ObservationLearner.Frame f){Map<String,float[]> m=new HashMap<>();for(PhaseEngine.Region r:e.activeRegions())m.put(r.id,f.sample(r.bounds));return m;}
 static PhaseEngine.Watch observed(PhaseEngine e,ObservationLearner.Frame f,long at){Map<String,float[]> m=samples(e,f);e.observe(m,at);check(e.poll()==null,"first independent observation waits");e.observe(m,at+100);return e.poll();}
 public static void main(String[] args){
  ObservationLearner.Frame a=frame(0),b=frame(1),c=frame(2);
  check(ObservationLearner.same(a,a,a,a),"same display is the same state");check(!ObservationLearner.same(a,a,b,b),"different display is a different state");check(!ObservationLearner.same(b,b,a,a),"equality is symmetric");
  int[] cornerPixels=a.pixels.clone();for(int y=0;y<a.height/15;y++)for(int x=a.width*15/16;x<a.width;x++)cornerPixels[y*a.width+x]=((x+y)%2==0?0xfff04020:0xff20f040);ObservationLearner.Frame corner=new ObservationLearner.Frame(a.width,a.height,cornerPixels);check(!ObservationLearner.same(a,a,corner,corner),"a small corner change is not silently merged");
  int[] blankPixels=new int[32*64];Arrays.fill(blankPixels,0xff000000);ObservationLearner.Frame blank=new ObservationLearner.Frame(32,64,blankPixels);check(ObservationLearner.same(blank,null,blank,null),"equality remains reflexive for a uniform screen");
  ObservationLearner learner=new ObservationLearner();learner.add(step(a,b,.31f,.26f));learner.add(step(b,a,.7f,.76f));ObservationLearner.Result r=learner.compile(true);PhaseEngine e=r.engine;
  check(r.states==2&&r.loops,"round trip has exactly two visual states");check(e.windowRelative&&e.validate().isEmpty(),"learned engine validates and uses local coordinates");
  PhaseEngine.Watch input=observed(e,a,0);check(input!=null&&input.action==PhaseEngine.CENTER,"taught tap is selected");check(input.touchPoint[0]==.31f&&input.touchPoint[1]==.26f,"tap point is independent of monitor center");String start=e.current;e.finish(input,101);check(e.current.contains("verify"),"input success enters display confirmation, not destination");
  e.observe(samples(e,a),110);e.observe(samples(e,a),210);check(e.poll()==null,"old screen cannot advance destination");PhaseEngine.Watch confirmed=observed(e,b,300);check(confirmed!=null&&confirmed.action==PhaseEngine.WAIT,"actual destination confirms transition");e.finish(confirmed,401);check(!e.current.equals(start)&&e.current.contains("state"),"different screen enters different state");
  check(e.activeRegions().size()<=3,"routine sampling is current-state scoped");PhaseEngine.Watch back=observed(e,b,500);e.finish(back,601);PhaseEngine.Watch home=observed(e,a,700);e.finish(home,801);check(e.current.equals(start),"same screen returns to exactly the same state");
  PhaseEngine copy=e.runtimeCopy();PhaseEngine.Watch cw=copy.rule(input.id);cw.touchPoint[0]=.9f;cw.guardReferences[0][0]=.9f;check(e.rule(input.id).touchPoint[0]==.31f&&e.rule(input.id).guardReferences[0][0]!=.9f,"runtime copy cannot mutate recorded coordinates or guards");
  learner=new ObservationLearner();learner.add(step(a,b,.3f,.25f));learner.add(step(b,a,.7f,.75f));learner.add(step(a,c,.3f,.25f));r=learner.compile(true);e=r.engine;
  check(r.states==3,"same source is merged across multiple observed destinations");check(e.phases.get(e.initial).watches.size()==1,"same state and action use one input arrow");input=e.phases.get(e.initial).watches.get(0);check(e.phases.get(input.nextPhase).watches.size()==2,"one operation can verify two recorded destinations");
  learner=new ObservationLearner();learner.add(step(a,b,.3f,.25f));learner.add(step(b,a,.7f,.75f));learner.add(step(a,c,.6f,.75f));r=learner.compile(true);e=r.engine;check(r.ambiguousStates==1,"identical display with different actions is reported");e.observe(samples(e,a),0);e.observe(samples(e,a),100);check(e.poll()==null&&e.diagnostic.contains("複数"),"ambiguous action never chooses arbitrarily");
  learner=new ObservationLearner();ObservationLearner.Step marker=step(a,b,.5f,.75f);marker.action=PhaseEngine.MARKERS;marker.markerIds=new String[]{"existing-marker"};marker.markerPoints=new float[]{.5f,.75f};marker.duration=300;learner.add(marker);r=learner.compile(true);input=r.engine.phases.get(r.engine.initial).watches.get(0);check(input.action==PhaseEngine.MARKERS&&input.markerIds[0].equals("existing-marker")&&input.markerPoints[1]==.75f,"existing marker identity and local position are preserved");check(r.engine.phases.get(input.nextPhase).watches.get(0).nextPhase.endsWith("state:1"),"unknown final screen receives its own terminal state");
  learner=new ObservationLearner();ObservationLearner.Step curve=step(a,b,.3f,.25f);curve.action=PhaseEngine.CURVE;curve.path=new float[]{.2f,.3f,.35f,.6f,.7f,.75f};curve.duration=680;learner.add(curve);r=learner.compile(false);input=r.engine.phases.get(r.engine.initial).watches.get(0);check(input.relativeCurve&&input.curve.length==6&&input.duration==680,"demonstrated curve keeps path and duration");check(r.engine.phases.get(input.nextPhase).watches.get(0).action==PhaseEngine.STOP,"one-pass mode stops only after final display confirmation");
  try{learner=new ObservationLearner();learner.compile(true);throw new AssertionError();}catch(IllegalStateException expected){checks++;}
  try{ObservationLearner.Step invalid=step(a,b,1.1f,.3f);new ObservationLearner().add(invalid);throw new AssertionError();}catch(IllegalArgumentException expected){checks++;}
  e=r.engine;input=e.phases.get(e.initial).watches.get(0);e.enter(e.initial,0);Map<String,float[]> m=samples(e,a);m.remove(input.guardIds[0]);e.observe(m,0);e.observe(m,100);check(e.poll()==null,"missing auxiliary evidence blocks an action");
  System.out.println("PASS "+checks+" on-device automaton learning checks");
 }
}
